(Get-Content ./client/src/Cloudmersive.APIClient.NETCore.Phishing/Cloudmersive.APIClient.NETCore.Phishing.csproj).replace('<Company>Swagger</Company>', "<Company>Cloudmersive</Company>") | Set-Content ./client/src/Cloudmersive.APIClient.NETCore.Phishing/Cloudmersive.APIClient.NETCore.Phishing.csproj
(Get-Content ./client/src/Cloudmersive.APIClient.NETCore.Phishing/Cloudmersive.APIClient.NETCore.Phishing.csproj).replace('<AssemblyTitle>Swagger Library</AssemblyTitle>', "<AssemblyTitle>Cloudmersive Phishing Detection API Client</AssemblyTitle>") | Set-Content ./client/src/Cloudmersive.APIClient.NETCore.Phishing/Cloudmersive.APIClient.NETCore.Phishing.csproj
(Get-Content ./client/src/Cloudmersive.APIClient.NETCore.Phishing/Cloudmersive.APIClient.NETCore.Phishing.csproj).replace('<Description>A library generated from a Swagger doc</Description>', "<Description>Detect Phishing and Business Email Compromise attacks in links and URLs.</Description>") | Set-Content ./client/src/Cloudmersive.APIClient.NETCore.Phishing/Cloudmersive.APIClient.NETCore.Phishing.csproj
(Get-Content ./client/src/Cloudmersive.APIClient.NETCore.Phishing/Cloudmersive.APIClient.NETCore.Phishing.csproj).replace('<TargetFramework>net45</TargetFramework>', "<TargetFramework>netcoreapp2.1</TargetFramework>") | Set-Content ./client/src/Cloudmersive.APIClient.NETCore.Phishing/Cloudmersive.APIClient.NETCore.Phishing.csproj
(Get-Content ./client/src/Cloudmersive.APIClient.NETCore.Phishing/Cloudmersive.APIClient.NETCore.Phishing.csproj).replace('</PropertyGroup>', "<PackageIconUrl>https://cloudmersive.com/images/cmsdk_core.png</PackageIconUrl><PackageLicenseExpression>Apache-2.0</PackageLicenseExpression><PackageProjectUrl>https://cloudmersive.com/phishing-detection-api</PackageProjectUrl></PropertyGroup>") | Set-Content ./client/src/Cloudmersive.APIClient.NETCore.Phishing/Cloudmersive.APIClient.NETCore.Phishing.csproj
(Get-Content '.\client\src\Cloudmersive.APIClient.NETCore.Phishing\Cloudmersive.APIClient.NETCore.Phishing.csproj').replace('<PackageReference Include="RestSharp" Version="105.1.0" />', '<PackageReference Include="RestSharp" Version="106.6.10" />') | Set-Content '.\client\src\Cloudmersive.APIClient.NETCore.Phishing\Cloudmersive.APIClient.NETCore.Phishing.csproj'
(Get-Content '.\client\src\Cloudmersive.APIClient.NETCore.Phishing\Client\ApiClient.cs').replace('request.AddFile(param.Value.Name, param.Value.Writer, param.Value.FileName, param.Value.ContentType);', 'request.AddFile(param.Value.Name, param.Value.Writer, param.Value.FileName, param.Value.ContentLength, param.Value.ContentType);') | Set-Content '.\client\src\Cloudmersive.APIClient.NETCore.Phishing\Client\ApiClient.cs'

